window.__SITE_EN={"Lingo Loop — Trò chuyện để nói thành thạo":"Lingo Loop — Talk your way to fluent","Chuyển đến nội dung chính":"Skip to content","Học thử ngay":"Try a lesson","Vòng lặp":"The loop","Ngôn ngữ":"Languages","Gói học":"Plans","Học miễn phí":"Start free","Trò":"Talk","chuyện":"story","để":"way","nói":"to","thành thạo.":"fluent.","Lingo Loop là gia sư bỏ túi dạy bạn ngoại ngữ theo đúng cách bạn giao tiếp ngoài đời thực — qua những đoạn hội thoại ngắn gọn, sống động. Chọn câu đáp lại, nhận góp ý tức thì và quay lại vào ngày mai để tiến bộ hơn.":"Lingo Loop is a pocket tutor that teaches you the way you'll actually use a language — in short, real conversations. Pick a reply, get instant feedback, and come back tomorrow for more.","Thử bài học 2 phút":"Try a 2-minute lesson","Cách hoạt động":"How it works","12 ngôn ngữ":"12 languages","5 phút mỗi ngày":"5 minutes a day","Không nhồi nhét ngữ pháp":"No grammar drills","Thử ngay — không cần đăng ký":"Try it now — no sign-up","Bài học đầu tiên,":"Your first lesson,","ngay tại đây.":"right here.","Bốn lượt thoại trong một tình huống đời thực. Chạm vào câu trả lời bạn muốn nói. Lou sẽ cho bạn biết ngay người bản xứ có nói như vậy không — và vì sao.":"Four lines of a real conversation. Tap the reply you'd say. Lou tells you instantly if a local would say it that way — and why.","Tây Ban Nha":"Spanish","Tiếng Pháp":"French","Tiếng Ý":"Italian","ngày liên tiếp":"day streak","Tiếp tục":"Continue","Chào bạn! Mình là Lou. Cùng gọi một ly cà phê ở Madrid nhé.":"Hi! I'm Lou. Let's order a coffee in Madrid.","Mẹo: nhấn phím":"Tip: press","hoặc":"or","để chọn đáp án,":"to answer,","để tiếp tục.":"to continue.","Mỗi ngày một vòng lặp.":"One loop a day.","Lắng nghe":"Hear it","Những hoạt cảnh ngắn do người bản xứ lồng tiếng — tại quán cà phê, nhà ga hay phòng chờ khám bệnh. Tuyệt đối không có những câu vô nghĩa kiểu \"con mèo uống sữa\".":"Short scenes voiced by native speakers — cafés, train stations, a doctor's waiting room. Never \"the cat drinks milk\".","Mở lời":"Say it","Trả lời thành tiếng hoặc chạm chọn câu thoại. Lou ưu tiên lắng nghe ý nghĩa trước rồi mới chỉnh phát âm, giúp bạn tự tin nói tiếp thay vì khựng lại.":"Answer out loud or tap a reply. Lou listens for meaning first and accent second, so you keep talking instead of freezing.","Tinh chỉnh":"Fix it","Mỗi chỗ chưa chuẩn đều có một dòng giải thích ngắn gọn kèm cách diễn đạt tự nhiên nhất của người bản xứ. Không gạch bút đỏ, không lý thuyết dài dòng.":"Every slip gets a one-line why, plus the phrase a local would actually use. No red ink, no lectures.","Ghi nhớ":"Keep it","Những từ bạn từng ngập ngừng sẽ quay lại ngay trước khi bạn kịp quên. Chỉ cần năm phút mỗi ngày là đủ để biến từ vựng thành phản xạ lâu dài.":"Words you miss come back just before you'd forget them. Five minutes a day is enough to keep them for good.","Ứng dụng":"App","Mỗi tuần khép lại bằng một cuộc trò chuyện tự do theo chủ đề bạn chọn — bóng đá, điện ảnh hay công thức nấu ăn của bà.":"Each week ends with an unscripted chat on a topic you choose — football, film, your grandmother's recipes.","Chạm vào thẻ để lật xem câu mẫu":"Tap a card to flip it","Chào thế giới bằng mười hai thứ tiếng.":"Say hello in twelve.","Một tuần học tập mẫu":"A sample learner's week","Tích tiểu thành đại.":"Small days add up.","Tuần này":"This week","Hoàn thành bài học phía trên để thắp sáng hôm nay.":"Finish today's lesson above to light up today.","Số phút":"Minutes","Huy hiệu":"Badges","Khách quen quán cà phê":"Café regular","Cú đêm chăm chỉ":"Night owl","Cuộc trò chuyện đầu tiên":"First full chat","Từ vựng làm chủ":"Words you own","Đã gặp, đã dùng và vẫn nhớ rõ sau một tuần.":"Seen, used and remembered a week later.","Học viên trên hành trình.":"Learners, mid-loop.","\"Mình đã tự gọi bữa tối ở Osaka mà không cần chỉ tay vào thực đơn lần nào. Người yêu mình đã quay video lại. Mỗi khi lười học mình lại mở ra xem.\"":"\"I ordered dinner in Osaka without pointing at the menu once. My partner filmed it. I watch it when I want to skip a day.\"","Tiếng Nhật · chuỗi 112 ngày":"Japanese · 112-day streak","\"Phần nhận xét thực sự đáng giá. Ứng dụng không chỉ báo sai, mà chỉ rõ người Paris thực sự sẽ nói thế nào — và thường ngắn gọn hơn hẳn.\"":"\"The feedback is the thing. It doesn't just say wrong, it says what a Parisian would say instead — and it's usually shorter.\"","Tiếng Pháp · chuỗi 48 ngày":"French · 48-day streak","\"Năm phút trên xe buýt mỗi sáng. Sáu tháng sau mình đã có thể trò chuyện thực sự với bà ngoại bằng tiếng Ý.\"":"\"Five minutes on the bus every morning. Six months later I had a real conversation with my nonna in Italian.\"","Tiếng Ý · chuỗi 203 ngày":"Italian · 203-day streak","Bao lâu bạn sẽ giao tiếp tự tin?":"How fast will you get there?","Nhịp độ của bạn":"Your pace","Số phút mỗi ngày:":"Minutes a day:","Bạn có thể trò chuyện tự nhiên suốt 10 phút sau khoảng":"You could hold a 10-minute conversation in about","26 tuần":"26 weeks","/ tháng, thanh toán theo năm":"/ month, billed yearly","Học không giới hạn cả 12 ngôn ngữ":"Unlimited lessons in all 12 languages","Trò chuyện tự do hàng tuần cùng Lou":"Weekly free-form chats with Lou","Chế độ ngoại tuyến khi di chuyển":"Offline mode for the commute","Bảo lưu chuỗi ngày học khi bạn bận đột xuất":"Streak freezes for the days life happens","Hoặc học miễn phí trọn đời với một bài học mỗi ngày.":"Or stay free forever with one lesson a day.","Bắt đầu 7 ngày dùng thử":"Start your 7-day trial","Vòng lặp đầu tiên chỉ mất hai phút.":"Your first loop takes two minutes.","Ngày mai Lou vẫn ở đây đợi bạn. Bí quyết chỉ đơn giản vậy thôi.":"Lou will be here tomorrow too. That's sort of the point.","Bắt đầu trò chuyện":"Start talking","Thiết kế concept — thương hiệu giả định.":"Concept design — fictional brand.","Trang chủ Lingo Loop":"Lingo Loop home","Điều hướng chính":"Main","Mở menu":"Open menu","Trò chuyện để nói thành thạo.":"Talk your way to fluent.","Chọn ngôn ngữ":"Choose a language","Mục tiêu XP hằng ngày":"Daily XP goal","Chuỗi ngày học":"Day streak","Chọn câu trả lời của bạn":"Choose your reply","Gia sư của bạn":"Your tutor","Đóng menu":"Close menu","Lingo Loop là gia sư ngoại ngữ AI dạy bạn qua những cuộc trò chuyện thực tế ngắn gọn — kèm phản hồi tức thì, điểm kinh nghiệm XP và chuỗi ngày học giữ lửa động lực.":"Lingo Loop is an AI language tutor teaching through bite-sized realistic conversations — with instant feedback, XP rewards, and streaks to keep momentum alive.","Quán cà phê trên phố Calle de Atocha, Madrid":"Café on Calle de Atocha, Madrid","¡Hola! ¿Qué te pongo?":"¡Hola! ¿Qué te pongo?","Xin chào! Tôi có thể phục vụ bạn món gì?":"Hello! What can I get for you?","Un café con leche, por favor.":"Un café con leche, por favor.","Chuẩn xác — thêm \"por favor\" ở cuối câu là cách gọi đồ tự nhiên nhất của người bản xứ.":"Spot on — adding \"por favor\" at the end is the most natural way locals order.","Yo quiero café.":"Yo quiero café.","Người nghe vẫn hiểu, nhưng hơi cụt lủn. Người bản xứ sẽ nói \"Un café con leche, por favor.\"":"They'll understand, but it's a bit blunt. A native speaker would say \"Un café con leche, por favor.\"","Me llamo café.":"Me llamo café.","Câu này nghĩa là \"Tên tôi là cà phê\". Đáng yêu đấy, nhưng chưa đúng rồi!":"That translates to \"My name is coffee\". Charming, but not quite right!","¿Para tomar aquí o para llevar?":"¿Para tomar aquí o para llevar?","Bạn dùng tại quán hay mang đi?":"For here or to go?","Sí, por favor.":"Sí, por favor.","Lịch sự đấy, nhưng đây là câu hỏi lựa chọn. Hãy chọn một: \"Para llevar, gracias.\"":"Polite, but this is a choice question. Pick one: \"Para llevar, gracias.\"","Tuyệt vời. \"Para llevar\" có nghĩa là mang đi.":"Great choice. \"Para llevar\" means to take away.","Câu đó nghĩa là \"Tôi hai mươi tuổi\" — nhân viên pha chế không hỏi tuổi bạn đâu.":"That means \"I am twenty years old\" — the barista isn't checking your ID.","Của bạn hết hai euro năm mươi xu.":"That will be two euros fifty.","\"Chúc ngủ ngon\" — hơi sớm cho một buổi sáng đi mua cà phê.":"\"Good night\" — a little early for a morning coffee run.","¿Cuánto cuesta?":"¿Cuánto cuesta?","Họ vừa báo giá cho bạn rồi! Nếu nghe chưa rõ, hãy nói \"Perdón, ¿cuánto es?\"":"They just told you the total! If you didn't catch it, try \"Perdón, ¿cuánto es?\"","Aquí tiene.":"Aquí tiene.","\"Gửi bạn đây\" — câu cửa miệng lịch sự khi bạn đưa tiền cho nhân viên.":"\"Here you go\" — the polite standard phrase when handing over payment.","¡Gracias! ¡Que tengas un buen día!":"¡Gracias! ¡Que tengas un buen día!","Cảm ơn! Chúc bạn một ngày tốt lành!":"Thank you! Have a great day!","\"Bạn cũng vậy nhé!\" — lời đáp tự nhiên nhất ở Tây Ban Nha.":"\"You too!\" — the most natural parting reply in Spain.","\"Không có gì\" thường dùng sau lời cảm ơn, nhưng ở đây \"¡Igualmente!\" hợp ngữ cảnh hơn nhiều.":"\"You're welcome\" works after thanks, but \"¡Igualmente!\" is far more natural here.","Câu đó nghĩa là \"Tôi xin lỗi\". Bạn đâu làm gì sai!":"That means \"I'm sorry\". You haven't done anything wrong!","café con leche":"café con leche","aquí tiene":"aquí tiene","Tiệm bánh mì trên phố Rue Mercière, Lyon":"Bakery on Rue Mercière, Lyon","Bonjour! Cùng mua bánh mì ở Lyon nhé — nhớ chào trước tiên.":"Bonjour! Let's pick up bread in Lyon — remember greetings come first.","Xin chào! Tôi có thể lấy gì cho bạn?":"Hello! What can I get for you?","Đúng từ vựng, nhưng ở Pháp bạn luôn phải chào trước: \"Bonjour, une baguette, s'il vous plaît.\"":"Vocabulary is fine, but in France always greet first: \"Bonjour, une baguette, s'il vous plaît.\"","Parfait. Chào hỏi trước là quy tắc vàng tại các cửa tiệm ở Pháp.":"Parfait. Greeting first is the golden rule in French shops.","Câu đó nghĩa là \"Tôi là một ổ bánh mì que\". Táo bạo đấy, nhưng sai rồi.":"That means \"I am a baguette\". Bold assertion, but not correct.","Bạn thích bánh nướng kỹ hay vừa chín tới?":"Do you prefer it well-baked or lightly done?","Rất chuẩn — nhiều người ở Lyon thích vỏ bánh vàng dịu vừa tới.":"Spot on — many in Lyon prefer a tender, lightly baked crust.","\"Trời đang mưa.\" Đúng với thời tiết Lyon, nhưng lệch câu hỏi rồi.":"\"It's raining.\" True for Lyon weather, but doesn't answer the question.","Đây là câu hỏi lựa chọn. Hãy thử nói \"Pas trop cuite, merci.\"":"This is an either-or choice. Try saying \"Pas trop cuite, merci.\"","Bạn có lấy thêm gì nữa không?":"Will that be all today?","Trả lời mỗi chữ \"non\" nghe hơi lạnh lùng. Hãy thử \"Oui, c'est tout, merci.\"":"Just saying \"non\" sounds abrupt. Try \"Oui, c'est tout, merci.\"","À demain.":"À demain.","\"Hẹn gặp ngày mai\" — bạn còn chưa thanh toán mà!":"\"See you tomorrow\" — you haven't paid yet!","Chính xác. Lịch sự và trọn vẹn ý.":"Exactly right. Polite and complete.","Ça fait un euro vingt. Bonne journée !":"Ça fait un euro vingt. Bonne journée !","Của bạn hết một euro hai mươi xu. Chúc một ngày tốt lành!":"That's one euro twenty. Have a great day!","Merci, bonne journée à vous aussi !":"Merci, bonne journée à vous aussi !","Rất tự nhiên. \"À vous aussi\" nghĩa là \"bạn cũng vậy nhé\".":"Very natural. \"À vous aussi\" means \"to you as well\".","\"Chào buổi tối\" — nhầm buổi cho một ổ bánh mì sáng rồi.":"\"Good evening\" — wrong time of day for morning bread.","Ổn! Nhưng chúc lại \"bonne journée\" mới đúng phong cách người bản xứ.":"Decent! But wishing \"bonne journée\" back is how locals do it.","bonne journée":"bonne journée","Quầy vé nhà ga Milano Centrale":"Ticket counter at Milano Centrale","Ciao! Cùng mua vé tàu đi Rome nhé.":"Ciao! Let's buy a train ticket to Rome.","Chào buổi sáng! Bạn đi đâu?":"Good morning! Where are you traveling to?","Câu đó nghĩa là \"Tôi đến từ Rome\" — không phải nơi bạn muốn đi tới.":"That means \"I come from Rome\" — not where you want to travel to.","Perfetto. \"Un biglietto per…\" là mẫu câu chuẩn để mua vé đi bất cứ đâu.":"Perfetto. \"Un biglietto per…\" is the standard formula to buy tickets anywhere.","Họ vẫn hiểu, nhưng nói đầy đủ \"Un biglietto per Roma, per favore\" sẽ thân thiện hơn.":"Understood, but saying \"Un biglietto per Roma, per favore\" is friendlier.","Vé một chiều hay khứ hồi?":"One-way or round-trip?","Tuyệt vời — \"andata e ritorno\" là vé khứ hồi.":"Spot on — \"andata e ritorno\" means round-trip.","Sì.":"Sì.","Đây là câu hỏi lựa chọn. Hãy chọn rõ: \"Andata e ritorno, grazie.\"":"This is an either-or question. State clearly: \"Andata e ritorno, grazie.\"","\"Tôi đói bụng.\" Dễ hiểu khi ở nhà ga đấy, nhưng chưa đúng câu hỏi.":"\"I am hungry.\" Relatable at a station, but doesn't answer the prompt.","Của bạn hết bốn mươi lăm euro.":"That comes to forty-five euros.","\"Chúc ngủ ngon\" — không hợp hoàn cảnh lúc này.":"\"Good night\" — out of place in this scenario.","Ổn! Bạn cũng có thể hỏi thêm \"Posso pagare con la carta?\"":"Fine! You could also ask \"Posso pagare con la carta?\"","\"Tôi thanh toán bằng thẻ được không?\" — câu hỏi cực hữu ích khắp nước Ý.":"\"Can I pay by card?\" — an essential everyday phrase across Italy.","Đường ray số bảy. Chúc thượng lộ bình an!":"Track seven. Have a safe journey!","\"Prego\" dùng để đáp lại lời cảm ơn. Ở đây hãy nói \"Grazie mille!\"":"\"Prego\" is used to say \"you're welcome\". Here, say \"Grazie mille!\"","\"Cảm ơn rất nhiều!\" — ấm áp và tự nhiên.":"\"Thank you so much!\" — warm and authentic.","\"Xin lỗi, mấy giờ rồi ạ?\" Hãy nhìn bảng điện tử trên sân ga nhé!":"\"Excuse me, what time is it?\" Check the departure board overhead!","Hôm nay đã sáng đèn. Hẹn gặp lại bạn ngày mai nhé!":"Streak lit for today. See you tomorrow!","Xem bản dịch":"Show translation","Ẩn bản dịch":"Hide translation","Chuẩn luôn!":"Spot on!","Nói như người bản xứ!":"Like a native!","Tuyệt vời!":"Brilliant!","Gần chuẩn rồi — chỉnh nhẹ một chút nhé.":"Almost there — minor adjustment needed.","Chưa đúng rồi! Thử lại lần nữa nhé.":"Not quite! Give it another shot.","Chính xác!":"Correct!","Gần chuẩn!":"Almost!","Chưa chính xác":"Incorrect","Chưa có XP":"No XP yet","Thử lại":"Try again","Hoàn thành bài học":"Lesson complete","Đến lượt bạn trả lời…":"Your turn to respond…","XP hôm nay":"Today's XP","đúng ngay lần đầu":"first-try accuracy","Từ vựng bạn vừa thu nạp:":"Vocabulary you picked up:","Học lại":"Practice again","Thử {0}":"Try {0}","Đã đạt mục tiêu ngày — chuỗi {0} ngày liên tiếp!":"Daily goal met — {0} day streak!","Tuyệt lắm! Còn {0} XP nữa là đạt mục tiêu hôm nay.":"Great work! {0} XP left to hit today's goal.","¿Dónde está la estación?":"¿Dónde está la estación?","Nhà ga ở đâu vậy ạ?":"Where is the train station?","9 tình huống":"9 scenarios","Je voudrais un café, s'il vous plaît.":"Je voudrais un café, s'il vous plaît.","Cho tôi một ly cà phê ạ.":"A coffee, please.","Tiếng Nhật":"Japanese","Cho tôi lấy món này ạ.":"I'll have this one, please.","8 tình huống":"8 scenarios","Cho tôi xin hóa đơn thanh toán.":"The bill, please.","Tiếng Đức":"German","Làm sao để tôi đến được nhà ga?":"How do I get to the train station?","7 tình huống":"7 scenarios","Bồ Đào Nha":"Portuguese","Olá!":"Olá!","Bạn có thể nói chậm hơn một chút không?":"Could you speak a little slower, please?","Tiếng Hàn":"Korean","Món này giá bao nhiêu vậy ạ?":"How much does this cost?","6 tình huống":"6 scenarios","Tiếng Việt":"Vietnamese","Xin chào":"Hello","Cho tôi một ly cà phê sữa đá.":"An iced milk coffee, please.","Gọi món cà phê truyền thống Việt Nam.":"Order a traditional Vietnamese iced coffee.","{0} · từ cơ bản đến B1":"{0} · beginner to B1","{0} tuần":"{0} weeks","Tức là vào khoảng {0} nếu bạn bắt đầu ngay hôm nay.":"Target completion around {0} if you start today.","Nói":"Speak","Sửa":"Correct","Nhớ":"Retain","Dùng":"Apply"};
